document.getElementById('logout').onclick=async()=>{await call('/api/logout',{});location.href='/?role=admin'};

(async()=>{try{const user=await call('/api/me');if(user.role!=='admin'){location.href='/?role=admin';return}await loadStaff()}catch{location.href='/?role=admin'}})();

