(()=>{

const el=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

async function api(url,body){const res=await fetch(url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const value=await res.json();if(!res.ok)throw Error(value.error||'Request failed');return value}

function status(id,text,error=false){el(id).textContent=text;el(id).style.color=error?'#b91c1c':'#166534'}

function table(headers,rows){return '<table><thead><tr>'+headers.map(v=>'<th>'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}

async function download(url,format,statusId){status(statusId,'Preparing '+format.toUpperCase()+' report…');try{const response=await fetch(url);if(!response.ok)throw Error((await response.json()).error||'Export failed');const blob=await response.blob(),link=document.createElement('a'),objectUrl=URL.createObjectURL(blob);link.href=objectUrl;link.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'report.'+format;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),60000);status(statusId,'Report downloaded.')}catch(e){status(statusId,e.message,true)}}

function examUrl(format='json'){const date=el('examDate').value;if(!date)throw Error('Select an exam date');return '/api/reports/exams?'+new URLSearchParams({date,timeZone:el('examTimezone').value,topic:el('examSubject').value,benchmark:el('examBenchmark').value,format})}

window.refreshReportAccounts=async()=>{if(!el('resetAccount'))return;const users=await api('/api/admin/users');el('resetAccount').innerHTML='<option value="">Choose an account</option>'+users.map(u=>`<option value="${u.id}">${esc(u.display_name||u.username)} — ${esc(u.username)} (${esc(u.role)})</option>`).join('')};

async function setup(){const user=await api('/api/me');const isAdmin=user.role==='admin';document.querySelectorAll('[data-admin-only]').forEach(node=>node.hidden=!isAdmin);

 if(el('examReportForm')){

  const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));el('examDate').value=parts.year+'-'+parts.month+'-'+parts.day;

  if(!isAdmin&&!user.canReport){el('examReportForm').hidden=true;status('examStatus','Your administrator has disabled student marks reports.',true)}else{

   const topics=await api('/api/topics');el('examSubject').innerHTML='<option value="">All permitted subjects</option>'+topics.map(t=>`<option value="${esc(t.paper+' — '+t.topic)}">${esc(t.paper+' — '+t.topic)}</option>`).join('');

   el('examReportForm').onsubmit=async event=>{event.preventDefault();status('examStatus','Loading exam results…');try{const report=await api(examUrl());const a=report.analysis;el('examAnalysis').innerHTML='<div class="analysis-grid">'+[['Attempts',a.attempts],['Students',a.students],['Average',a.averagePercentage===null?'N/A':a.averagePercentage+'%'],['Highest',a.highestPercentage===null?'N/A':a.highestPercentage+'%'],['Lowest',a.lowestPercentage===null?'N/A':a.lowestPercentage+'%'],['At/above '+a.benchmark+'%',a.passed],['Pass rate',a.passRate===null?'N/A':a.passRate+'%']].map(([k,v])=>'<p>'+esc(k)+'<br><strong>'+esc(v)+'</strong></p>').join('')+'</div>';el('examPreview').innerHTML=report.rows.length?table(report.headers,report.rows):'<p>No student exam submissions on this date for the selected subject.</p>';status('examStatus',report.subtitle)}catch(e){el('examAnalysis').textContent='';el('examPreview').textContent='';status('examStatus',e.message,true)}};

   document.querySelectorAll('[data-exam-format]').forEach(button=>button.onclick=()=>{try{if(!el('examReportForm').reportValidity())return;download(examUrl(button.dataset.examFormat),button.dataset.examFormat,'examStatus')}catch(e){status('examStatus',e.message,true)}})

  }

 }

 if(!isAdmin)return;

 await window.refreshReportAccounts();

 el('resetPassword').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{if(form.elements.password.value!==form.elements.confirmPassword.value)throw Error('The two new passwords do not match');const result=await api('/api/admin/users/'+el('resetAccount').value+'/password',{password:form.elements.password.value});form.reset();status('resetStatus',result.message)}catch(e){status('resetStatus',e.message,true)}};

 el('changeAdminPassword').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{if(form.elements.password.value!==form.elements.confirmPassword.value)throw Error('The two new passwords do not match');await api('/api/account/password',{currentPassword:form.elements.currentPassword.value,password:form.elements.password.value});location.href='/?role=admin'}catch(e){status('ownPasswordStatus',e.message,true)}};

 const registrationUrl=format=>'/api/reports/registrations?'+new URLSearchParams({role:el('registrationRole').value,timeZone:'Asia/Kolkata',format});

 el('previewRegistrations').onclick=async()=>{try{const report=await api(registrationUrl('json'));el('registrationPreview').innerHTML=report.rows.length?table(report.headers,report.rows):'<p>No matching registrations.</p>';status('registrationStatus',report.rows.length+' accounts. Earlier registration dates may be unavailable.')}catch(e){status('registrationStatus',e.message,true)}};

 document.querySelectorAll('[data-registration-format]').forEach(button=>button.onclick=()=>download(registrationUrl(button.dataset.registrationFormat),button.dataset.registrationFormat,'registrationStatus'));

}

setup().catch(e=>{const node=el('examStatus');if(node)node.textContent=e.message});

})();

/student.js:
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=v=>v?new Date(v.includes('T')?v:v.replace(' ','T')+'Z').toLocaleString():'Not recorded';
function questionDiagram(q){return /^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(q.diagram_data_uri||'')?`<img src="${q.diagram_data_uri}" alt="${esc(q.diagram_alt||'Question diagram; text description is included in the question.')}" style="max-width:100%;height:auto;background:white">`:''}
let catalog=[],planApplied=false,current=null,answers={},saveTimer,ticker,clockOffset=0,sending=false,saveChain=Promise.resolve();
async function api(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){const e=Error(d.error||'Request failed');e.status=r.status;throw e}return d}
function message(text,error=false){$('pageStatus').textContent=text;$('pageStatus').className='status '+(error?'error':'success')}
function storageKey(){return 'mcq-draft-'+current.id}
function remember(){try{localStorage.setItem(storageKey(),JSON.stringify(answers))}catch{}}
function updateTopics(){const list=catalog.filter(t=>t.paper===$('paper').value);$('topic').innerHTML=list.map(t=>`<option>${esc(t.topic)}</option>`).join('');updatePracticeInfo()}
function updatePracticeInfo(){const t=catalog.find(t=>t.paper===$('paper').value&&t.topic===$('topic').value);$('practiceInfo').textContent=(t?.count||0)+' active questions in this topic. Balanced selection uses available rated questions and fills remaining places from the topic.'}
async function loadDashboard(){
 const [home,progress,history,topics]=await Promise.all([api('/api/learning/home'),api('/api/learning/progress'),api('/api/scores'),api('/api/topics')]);catalog=topics;clockOffset=Date.parse(home.serverTime)-Date.now();const previous=$('paper').value;$('paper').innerHTML=[...new Set(topics.map(t=>t.paper))].map(p=>`<option>${esc(p)}</option>`).join('');if(topics.some(t=>t.paper===previous))$('paper').value=previous;updateTopics();if(!planApplied){const params=new URLSearchParams(location.search);if(catalog.some(t=>t.paper===params.get('paper')&&t.topic===params.get('topic'))){$('paper').value=params.get('paper');updateTopics();$('topic').value=params.get('topic');updatePracticeInfo();if(params.get('due')==='1'){message('Your due topic is selected. Use Review due questions to begin.');$('reviewDue').hidden=false}}planApplied=true}
 $('announcements').innerHTML=home.announcements.map(a=>`<article class="item"><h3>${esc(a.title)}</h3><p class="question-text">${esc(a.message)}</p><small>${esc(a.group_name||'All students')} · ${localDate(a.created_at)}</small></article>`).join('')||'<p class="muted">No announcements yet.</p>';
 $('savedAttempts').innerHTML=home.active.map(a=>`<article class="item"><strong>${esc(a.title)}</strong> <span class="badge">${esc(a.mode)}</span><p>${a.deadline?'Deadline: '+localDate(a.deadline):'Practice - no time limit'}</p><button data-resume="${a.id}">Resume saved attempt</button></article>`).join('')||'<p class="muted">No unfinished attempts.</p>';
 const now=Date.now()+clockOffset;
 $('examList').innerHTML=home.exams.map(e=>{const ended=now>=Date.parse(e.endsAt),upcoming=now<Date.parse(e.startsAt),submitted=e.attempt_status==='submitted';return `<article class="item"><h3>${esc(e.title)}</h3><p>${esc(e.paper)} / ${esc(e.topic)} · ${e.question_count} questions · ${e.question_count*2} marks · ${e.duration_minutes} minutes${e.extraMinutes?` + ${e.extraMinutes} extra minutes`:""}</p><p>${localDate(e.startsAt)} to ${localDate(e.endsAt)}</p><p class="question-text">${esc(e.instructions)}</p><p class="muted">${esc(e.group_name||'All students')} · ${e.release_policy==='manual'?'Teacher releases results':'Results after submission'}</p>${submitted?`<button data-resume="${e.attempt_id}" class="secondary">View submission</button>`:e.attempt_id?`<button data-resume="${e.attempt_id}">Resume exam</button>`:ended?'<span class="badge">Missed / window closed</span>':upcoming?'<span class="badge">Upcoming</span>':`<button data-exam="${e.id}">Start exam</button>`}</article>`}).join('')||'<p class="muted">No exams assigned yet.</p>';
 $('progressList').innerHTML=progress.map(t=>`<article class="item"><h3>${esc(t.paper)} / ${esc(t.topic)} ${t.average!==null&&t.average<60?'<span class="badge">Needs practice</span>':''}</h3><p>${t.covered}/${t.count} questions covered · ${t.correctQuestions} latest answers correct · ${t.attempts} attempts</p><div class="progress"><span style="width:${t.count?Math.min(100,t.covered/t.count*100):0}%"></span></div><p>Average: ${t.average===null?'Not attempted':t.average+'%'} · Best: ${t.best===null?'N/A':t.best+'%'} · ${t.covered>=t.count?'Topic covered':'Keep practising'}</p></article>`).join('');
 $('history').innerHTML='<table><thead><tr><th>Topic</th><th>Mode</th><th>Marks</th><th>Date</th><th>Review</th></tr></thead><tbody>'+history.map(s=>`<tr><td>${esc(s.topic)}</td><td>${esc(s.mode)}</td><td>${s.resultsAvailable?s.marks+' / '+s.totalMarks:'Awaiting teacher release'}</td><td>${localDate(s.attempted_at)}</td><td>${s.hasReview?`<button class="secondary" data-score="${s.id}">Review</button>`:'Pending / unavailable'}</td></tr>`).join('')+'</tbody></table>';
 document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>resume(b.dataset.resume));document.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>openReadiness(home.exams.find(e=>e.id===Number(b.dataset.exam))));document.querySelectorAll('[data-score]').forEach(b=>b.onclick=async()=>{try{showResult(await api('/api/scores/'+b.dataset.score))}catch(e){message(e.message,true)}});
}
async function start(data){try{message('Loading questions…');const a=await api('/api/learning/attempts',data);openAttempt(a);message('')}catch(e){message(e.message,true)}}
async function resume(id){try{openAttempt(await api('/api/learning/attempts/'+id))}catch(e){message(e.message,true)}}
function openAttempt(a){$('examReadiness').hidden=true;clearInterval(ticker);current=a;clockOffset=Date.parse(a.serverTime)-Date.now();if(a.status==='submitted'){showResult(a);return}answers={...a.answers};try{const local=JSON.parse(localStorage.getItem(storageKey())||'{}');if(!a.deadline||Date.now()+clockOffset<Date.parse(a.deadline))answers={...answers,...local}}catch{}$('dashboard').hidden=true;$('result').hidden=true;$('activeAttempt').hidden=false;$('attemptTitle').textContent=a.title;$('attemptMode').textContent=a.mode==='practice'?'Practice: select an option to check the answer and read the explanation.':'Exam: answers are saved automatically. Correct answers stay hidden until results are released.';
 $('questions').innerHTML=a.questions.map((q,i)=>`<article class="item"><h3>${i+1}. <span class="question-text">${esc(q.question)}</span></h3><span class="badge">2 marks · ${esc(q.difficulty)}</span>${questionDiagram(q)}<div class="options">${['A','B','C','D'].map(letter=>`<label><input type="radio" name="q_${q.id}" value="${letter}" data-question="${q.id}" ${answers[q.id]===letter?'checked':''}><span>${letter}. ${esc(q['option_'+letter.toLowerCase()])}</span></label>`).join('')}</div><div id="feedback-${q.id}" role="status"></div><button type="button" class="secondary" data-report="${q.id}">Report question</button>${a.mode==='practice'?` <button type="button" class="secondary" data-notebook="${q.id}">Save to notebook</button>`:''}</article>`).join('');
 $('questions').querySelectorAll('input').forEach(input=>input.onchange=async()=>{answers[input.dataset.question]=input.value;remember();queueSave();if(current.mode==='practice')try{const feedback=await api('/api/learning/attempts/'+current.id+'/check',{questionId:Number(input.dataset.question),answer:input.value});const box=$('feedback-'+input.dataset.question);box.className='item '+(feedback.correct?'correct':'wrong');box.textContent=(feedback.correct?'Correct. ':'Incorrect. ')+`Correct answer: ${feedback.correctOption}. ${feedback.correctAnswer}. `+feedback.explanation}catch(e){$('saveStatus').textContent=e.message}});
 bindNotebookButtons($('questions'),a.id);
 $('questions').querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{const note=prompt('Describe the issue with this question. Staff will review your report.');if(!note)return;try{alert((await api('/api/support/flags',{attemptId:current.id,questionId:Number(b.dataset.report),message:note})).message)}catch(e){alert(e.message)}});
 $('saveStatus').textContent='Your saved answers have been restored.';queueSave();tick();ticker=setInterval(tick,1000);window.scrollTo({top:0,behavior:'smooth'});
}
function queueSave(){clearTimeout(saveTimer);$('saveStatus').textContent='Saving answers…';saveTimer=setTimeout(()=>save(),650)}
function save(){if(!current||current.status==='submitted')return Promise.resolve();remember();const id=current.id,copy={...answers};saveChain=saveChain.catch(()=>{}).then(async()=>{try{await api('/api/learning/attempts/'+id+'/save',{answers:copy});if(current?.id===id)$('saveStatus').textContent='Answers saved securely at '+new Date().toLocaleTimeString()}catch(e){if(current?.id===id)$('saveStatus').textContent=e.status===409?'Attempt ended. Submit or reload to view the result.':'Saved on this device. Waiting for connection to sync.'}});return saveChain}
function tick(){if(!current)return;if(!current.deadline){$('timer').textContent='Untimed practice';return}const remaining=Math.max(0,Math.ceil((Date.parse(current.deadline)-Date.now()-clockOffset)/1000));$('timer').textContent=`Time left ${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(!remaining&&!sending){clearInterval(ticker);submit(true)}}
async function submit(automatic=false){if(!current||sending)return;if(!automatic&&!confirm('Submit this attempt? Unanswered questions receive 0 marks.'))return;sending=true;clearTimeout(saveTimer);$('submitAttempt').disabled=true;try{if(!automatic)await save();const a=await api('/api/learning/attempts/'+current.id+'/submit',{answers});try{localStorage.removeItem(storageKey())}catch{}current=a;clearInterval(ticker);showResult(a);await loadDashboard()}catch(e){$('saveStatus').textContent=automatic?'Time ended. Reconnect and submit to grade the answers already saved on the server.':e.message;remember()}finally{sending=false;$('submitAttempt').disabled=false}}
function showResult(r){clearInterval(ticker);$('activeAttempt').hidden=true;$('dashboard').hidden=true;$('result').hidden=false;$('resultTitle').textContent=r.title||r.topic||'Quiz result';$('resultSummary').textContent=r.resultsAvailable===false?(r.message||'Awaiting teacher release'):`Total marks: ${r.marks} / ${r.totalMarks} (${r.score} correct out of ${r.total})`;const wrong=(r.review||[]).filter(q=>!q.correct);$('review').innerHTML=r.resultsAvailable===false?'<p>Marks and answers will appear after your teacher releases them.</p>':wrong.length?wrong.map(q=>`<article class="item wrong"><h3>Question ${q.number}: ${esc(q.question)}</h3>${questionDiagram(q)}<p>Your answer: ${q.selectedOption?esc(q.selectedOption+'. '+q.selectedAnswer):'Not answered'}</p><p><strong>Correct: ${esc(q.correctOption+'. '+q.correctAnswer)}</strong></p><p>${esc(q.explanation||'A detailed explanation has not been added yet.')}</p><p>0 / 2 marks</p>${(r.attemptId||typeof r.id==='string')&&q.questionId?`<button class="secondary" data-notebook="${q.questionId}">Save to notebook</button>`:''}</article>`).join(''):'<p>All answers correct, or no detailed review is available for this earlier attempt.</p>';bindNotebookButtons($('review'),r.attemptId||(typeof r.id==='string'?r.id:null));window.scrollTo({top:0,behavior:'smooth'})}
$('paper').onchange=updateTopics;$('topic').onchange=updatePracticeInfo;$('startPractice').onclick=()=>start({paper:$('paper').value,topic:$('topic').value,difficulty:$('difficulty').value,questionCount:Number($('practiceCount').value)});$('retryWrong').onclick=()=>start({paper:$('paper').value,topic:$('topic').value,difficulty:$('difficulty').value,questionCount:Number($('practiceCount').value),retryWrong:true});$('submitAttempt').onclick=()=>submit();$('saveExit').onclick=async()=>{await save();clearInterval(ticker);$('activeAttempt').hidden=true;$('dashboard').hidden=false;current=null;await loadDashboard()};$('backDashboard').onclick=async()=>{$('result').hidden=true;$('dashboard').hidden=false;current=null;await loadDashboard()};$('logout').onclick=async()=>{if(current?.status==='active')await save();await api('/api/logout',{});location.href='/?role=student'};window.addEventListener('offline',()=>$('networkStatus').hidden=false);window.addEventListener('online',()=>{$('networkStatus').hidden=true;if(current?.status==='active'){if(current.deadline&&Date.now()+clockOffset>=Date.parse(current.deadline))submit(true);else save()}});window.addEventListener('beforeunload',()=>{if(current?.status==='active')remember()});
