async function loadGroups(){groups=await api('/api/teaching/groups');const options='<option value="">All registered students</option>'+groups.map(g=>`<option value="${g.id}">${esc(g.name)} (${g.students.length} students)</option>`).join('');$('examGroup').innerHTML=options;$('announcementGroup').innerHTML=options;$('groupList').innerHTML=groups.map(g=>`<article class="item"><strong>${esc(g.name)}</strong><p>${g.students.length} students</p><button data-group="${g.id}" class="secondary">Edit members</button></article>`).join('')||'<p>No groups yet.</p>';document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{const g=groups.find(g=>g.id===Number(b.dataset.group));$('groupForm').elements.id.value=g.id;$('groupForm').elements.name.value=g.name;$('memberSearch').value='';renderMembers(g.students);$('groupForm').scrollIntoView({behavior:'smooth'})})}
$('groupForm').onsubmit=async event=>{event.preventDefault();try{const form=event.currentTarget;const r=await api('/api/teaching/groups',{id:Number(form.elements.id.value)||undefined,name:form.elements.name.value,students:[...$('members').querySelectorAll('input:checked')].map(x=>Number(x.value))});status('groupStatus',r.message);form.reset();renderMembers([]);await loadGroups()}catch(e){status('groupStatus',e.message,true)}};
async function loadExams(){const exams=await api('/api/teaching/exams');$('examList').innerHTML=exams.map(e=>`<article class="item"><h3>${esc(e.title)} ${e.cancelled?'<span class="badge">Cancelled</span>':''}</h3><p>${esc(e.paper)} / ${esc(e.topic)}${e.blueprint_json?' ('+esc(JSON.parse(e.blueprint_json).map(s=>s.topic+': '+s.count).join(', '))+')':''} · ${esc(e.group_name||'All students')} · ${e.question_count*2} marks</p><p>${local(e.starts_at)} to ${local(e.ends_at)} · ${e.duration_minutes} minutes</p><p>Access code: <strong>${esc(e.access_code||'Not required')}</strong> · Options ${e.shuffle_options?'shuffled':'in original order'}</p><p>${e.release_policy==='manual'&&!e.results_released?'Results awaiting your release':'Automatic / released results'}</p><div class="actions"><button data-attendance="${e.id}" class="secondary">View attendance and marks</button><a class="button secondary" href="/api/teaching/exams/${e.id}/attendance?format=pdf">Attendance PDF</a>${e.release_policy==='manual'&&!e.results_released?`<button data-release="${e.id}">Release results</button>`:''}<button data-cancel="${e.id}" data-state="${e.cancelled?0:1}" class="secondary">${e.cancelled?'Restore exam':'Cancel exam'}</button></div></article>`).join('')||'<p>No scheduled exams yet.</p>';document.querySelectorAll('[data-release]').forEach(b=>b.onclick=async()=>{if(!confirm('Release marks and answer reviews for this exam?'))return;try{const r=await api('/api/teaching/exams/'+b.dataset.release+'/release',{});status('examStatus',r.message);await loadExams()}catch(e){status('examStatus',e.message,true)}});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{const r=await api('/api/teaching/exams/'+b.dataset.cancel+'/cancel',{cancelled:b.dataset.state==='1'});status('examStatus',r.message);await loadExams()}catch(e){status('examStatus',e.message,true)}});document.querySelectorAll('[data-attendance]').forEach(b=>b.onclick=async()=>{try{const r=await api('/api/teaching/exams/'+b.dataset.attendance+'/attendance');$('attendance').innerHTML='<h3>'+esc(r.exam.title)+'</h3><div class="stats">'+Object.entries(r.summary).map(([k,v])=>'<p>'+esc(k)+'<br><strong>'+esc(v??'N/A')+'</strong></p>').join('')+'</div><table><thead><tr><th>Student</th><th>Username</th><th>Status</th><th>Marks</th><th>%</th></tr></thead><tbody>'+r.roster.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.username)}</td><td>${esc(s.status)}</td><td>${s.marks??'Pending'} / ${s.totalMarks}</td><td>${s.percentage??'N/A'}</td></tr>`).join('')+'</tbody></table>';$('attendance').scrollIntoView({behavior:'smooth'})}catch(e){status('examStatus',e.message,true)}})}
$('examForm').onsubmit=async event=>{event.preventDefault();const f=event.currentTarget,body=Object.fromEntries(new FormData(f));try{body.startsAt=new Date(body.startsAt).toISOString();body.endsAt=new Date(body.endsAt).toISOString();for(const key of ['questionCount','durationMinutes'])body[key]=Number(body[key]);body.groupId=Number(body.groupId)||null;body.shuffleOptions=body.shuffleOptions==='true';const r=await api('/api/teaching/exams',body);status('examStatus',r.message);await loadExams()}catch(e){status('examStatus',e.message,true)}};
async function loadAnnouncements(){const list=await api('/api/teaching/announcements');$('announcementList').innerHTML=list.map(a=>`<article class="item"><h3>${esc(a.title)} ${a.archived?'<span class="badge">Archived</span>':''}</h3><p class="question-text">${esc(a.message)}</p><p>${esc(a.group_name||'All students')}</p><button data-announcement="${a.id}" data-state="${a.archived?0:1}" class="secondary">${a.archived?'Restore':'Archive'}</button></article>`).join('');document.querySelectorAll('[data-announcement]').forEach(b=>b.onclick=async()=>{try{await api('/api/teaching/announcements',{id:Number(b.dataset.announcement),archived:b.dataset.state==='1'});await loadAnnouncements()}catch(e){status('announcementStatus',e.message,true)}})}
$('announcementForm').onsubmit=async event=>{event.preventDefault();try{const f=event.currentTarget,body=Object.fromEntries(new FormData(f));body.groupId=Number(body.groupId)||null;body.shuffleOptions=body.shuffleOptions==='true';const r=await api('/api/teaching/announcements',body);status('announcementStatus',r.message);f.reset();await loadAnnouncements()}catch(e){status('announcementStatus',e.message,true)}};$('logout').onclick=async()=>{await api('/api/logout',{});location.href='/?role=staff'};
(async()=>{try{user=await api('/api/me');if(!['staff','admin'].includes(user.role)){location.href='/?role=staff';return}$('identity').textContent=user.name+' / '+(user.subjectTitle||'All existing topics');$('adminLink').hidden=user.role!=='admin';$('newQuestion').disabled=user.role==='staff'&&!user.canUpload;$('timezoneInfo').textContent='Schedule times use your device timezone: '+Intl.DateTimeFormat().resolvedOptions().timeZone+'. Students see equivalent times in their own timezone.';const localInput=t=>new Date(t-new Date(t).getTimezoneOffset()*60000).toISOString().slice(0,16);$('examForm').elements.startsAt.value=localInput(Date.now()+600000);$('examForm').elements.endsAt.value=localInput(Date.now()+4200000);students=await api('/api/teaching/students');renderMembers([]);await Promise.all([loadQuestions(),loadGroups(),loadExams(),loadAnnouncements()])}catch(e){if(e.status===401)location.href='/?role=staff';else status('pageStatus',e.message,true)}})();
